// Inlined font and brand assets for zero-dependency PDF and Email generation
// Guarantees 100% reliability in bundled SSR, Docker, serverless, and production environments.

const ROBOTO_REGULAR_B64 = "";
const ROBOTO_BOLD_B64 = "";

let cachedRegular: Buffer | null = null;
let cachedBold: Buffer | null = null;

export function getReceiptRegularFont(): Buffer {
  if (!cachedRegular) {
    cachedRegular = Buffer.from(ROBOTO_REGULAR_B64, "base64");
  }
  return cachedRegular;
}

export function getReceiptBoldFont(): Buffer {
  if (!cachedBold) {
    cachedBold = Buffer.from(ROBOTO_BOLD_B64, "base64");
  }
  return cachedBold;
}

// Quickupp AI Studio logo, transparent background:
//  - navy lettering for the white PDF receipt
//  - white lettering (the website footer logo) for the dark header of the payment email
const LOGO_DARK_PNG_B64 = "";
const LOGO_WHITE_PNG_B64 = "";
let cachedLogoDark: Buffer | null = null;
let cachedLogoWhite: Buffer | null = null;
export function getCompanyLogoDarkBuffer(): Buffer {
  if (!cachedLogoDark) cachedLogoDark = Buffer.from(LOGO_DARK_PNG_B64, "base64");
  return cachedLogoDark;
}
export function getCompanyLogoWhiteBuffer(): Buffer {
  if (!cachedLogoWhite) cachedLogoWhite = Buffer.from(LOGO_WHITE_PNG_B64, "base64");
  return cachedLogoWhite;
}
